import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import {createHash} from 'node:crypto';
import {PhysicalSkyBridge} from '../integration/physical-sky-bridge.mjs';
const api=await import('../src/diffuse-assets.mjs').catch(()=>({}));const resilience=await import('../integration/resilient-sky-bridge.mjs').catch(()=>({}));
const cat=fs.readFileSync(new URL('../data/bright-stars.json',import.meta.url),'utf8'),raw=fs.readFileSync(new URL('../data/registered-starlight/V-nside32.json',import.meta.url),'utf8'),map=JSON.parse(raw),sha=x=>createHash('sha256').update(x).digest('hex');
const descriptor=(text,path,nside)=>({path,bytes:Buffer.byteLength(text),sha256:sha(text),...(nside?{nside,id:JSON.parse(text).id}:{})});
function manifest(){return {schema:'salah-real-sky/diffuse-runtime-manifest/1',sourceSha256:map.sourceSha256,catalogue:descriptor(cat,'data/bright-stars.json'),assets:Object.fromEntries(['32','64','128'].map(n=>{const t=fs.readFileSync(new URL('../data/registered-starlight/V-nside'+n+'.json',import.meta.url),'utf8');return [n,descriptor(t,'data/registered-starlight/V-nside'+n+'.json',+n)];}))};}
function create(m=manifest(),text=cat){assert.equal(typeof api.DiffuseAssetStore,'function');const bytes=JSON.stringify(m);return new api.DiffuseAssetStore(bytes,sha(bytes),text);}
const read=async p=>fs.readFileSync(new URL('../'+p,import.meta.url),'utf8');const defer=()=>{let resolve,reject;const promise=new Promise((a,b)=>{resolve=a;reject=b;});return {promise,resolve,reject};};
test('asset store verifies manifest pin, exact catalogue bytes, freezes fallback and begins unavailable',()=>{const s=create();assert.equal(s.snapshot.status,'idle');assert.equal(s.snapshot.binding,null);assert.ok(Object.isFrozen(s.catalogue.stars[0]));assert.throws(()=>new api.DiffuseAssetStore(JSON.stringify(manifest()),'0'.repeat(64),cat),/manifest.*hash/i);assert.throws(()=>create(manifest(),cat+' '),/catalogue.*(?:size|hash)/i);});
test('valid tier load has content-addressed identity; repeat request reuses bound source without stale frame cache',async()=>{const s=create();let calls=0;const a=await s.load('32',async p=>{calls++;return read(p);});assert.equal(a.status,'ready');const b=await s.load('32',async()=>{throw Error('cache should be used');});assert.equal(a.binding,b.binding);assert.equal(calls,1);assert.equal(b.cacheHit,true);assert.ok(s.snapshot.generation>a.generation);});
test('missing and corrupt data are failed closed per requested tier; no previous binding survives as current',async()=>{const s=create();await s.load('32',read);const missing=await s.load('64',async()=>{throw Error('404');});assert.equal(missing.status,'unavailable');assert.equal(missing.binding,null);assert.match(missing.error,/404/);const corrupt=await s.load('32',async()=>raw.replace('0.1','0.2'),{reload:true});assert.equal(corrupt.status,'unavailable');assert.equal(corrupt.binding,null);});
test('wrong version, unsupported source, paths and descriptor grid mismatch are rejected',()=>{for(const mutation of [m=>m.schema='future/2',m=>m.sourceSha256='0'.repeat(64),m=>m.assets['32'].path='../../secret',m=>m.assets['32'].nside=64,m=>m.assets['32'].bytes=1e12,m=>delete m.assets['64']]){const m=manifest();mutation(m);assert.throws(()=>create(m));}});
test('wrong tier bytes and radiance/mask changes are caught before binding despite equal total',async()=>{const s=create(),changed=JSON.parse(raw);changed.estimatedFraction[0]=1-changed.estimatedFraction[0];const a=await s.load('32',async()=>JSON.stringify(changed));assert.equal(a.status,'unavailable');const b=await s.load('64',async()=>raw);assert.equal(b.status,'unavailable');});
test('stale asynchronous success and stale failure cannot replace newest ready tier',async()=>{for(const fail of [false,true]){const s=create(),d=defer();const old=s.load('128',()=>d.promise);const current=await s.load('32',read);assert.equal(current.status,'ready');if(fail)d.reject(Error('late failure'));else d.resolve(await read('data/registered-starlight/V-nside128.json'));const stale=await old;assert.equal(stale.status,'superseded');assert.equal(s.snapshot.tier,'32');assert.equal(s.snapshot.status,'ready');assert.equal(s.snapshot.binding,current.binding);}});
test('invalid tier invalidates the preceding selection and reports an explicit error',async()=>{const s=create();await s.load('32',read);const bad=await s.load('4',read);assert.equal(bad.status,'unavailable');assert.equal(s.snapshot.binding,null);assert.match(bad.error,/tier/i);});
test('reload verifies again and drops the old cached identity; recovery returns actual verified data',async()=>{const s=create();const a=await s.load('32',read);await s.load('32',async()=>'',{reload:true});assert.equal(s.snapshot.status,'unavailable');const b=await s.load('32',read);assert.equal(b.status,'ready');assert.notEqual(a.binding,b.binding);});
test('dispose aborts active fetch, clears source cache, and late result cannot resurrect the store',async()=>{const s=create(),d=defer();let signal;const p=s.load('32',(_,{signal:sig})=>{signal=sig;return d.promise;});s.dispose();assert.ok(signal.aborted);d.resolve(raw);assert.equal((await p).status,'superseded');assert.equal(s.snapshot.status,'disposed');assert.equal(s.snapshot.binding,null);assert.equal((await s.load('32',read)).status,'disposed');});
test('diffuse-only failure preserves a fresh CP6 sky but invalid observer still clears all raster output',async()=>{assert.equal(typeof resilience.ResilientPhysicalSkyBridge,'function');const s=create(),bridge=new resilience.ResilientPhysicalSkyBridge(s),o={utcMs:Date.UTC(2026,0,15,2),latDeg:28.54,lonDeg:-81.38},options={view:{type:'camera',width:16,height:24},diffuse:{enabled:true,residualNight:{kind:'assumed-nonstellar-residual',zenithCdM2:.00014,source:'test',includesRegisteredStarlight:false}},nominalExposure:24};await s.load('32',async()=>{throw Error('missing');});const a=bridge.render(o,options);assert.equal(a.status,'ready');assert.equal(a.diffuseAsset.mode,'cp6-fallback');assert.equal(a.raster.diffuseState,undefined);const ref=new PhysicalSkyBridge(s.catalogue).render(o,{...options,diffuse:false});assert.deepEqual(a.raster.linear,ref.raster.linear);const b=bridge.render({...o,utcMs:o.utcMs+3600000},options);assert.notDeepEqual(b.raster.linear,a.raster.linear);const bad=bridge.render({...o,latDeg:NaN},options);assert.equal(bad.status,'unavailable');assert.equal(bad.raster,null);});
test('successful recovery uses the correct bound tier and does not conceal invalid physical configuration',async()=>{const s=create();assert.equal(typeof resilience.ResilientPhysicalSkyBridge,'function');const bridge=new resilience.ResilientPhysicalSkyBridge(s);await s.load('32',read);const o={utcMs:Date.UTC(2026,0,15,2),latDeg:28.54,lonDeg:-81.38},v={view:{type:'camera',width:16,height:24},diffuse:{enabled:true,residualNight:{kind:'assumed-nonstellar-residual',zenithCdM2:.00014,source:'test',includesRegisteredStarlight:false}}};const a=bridge.render(o,v);assert.equal(a.status,'ready');assert.equal(a.diffuseAsset.mode,'registered');assert.equal(a.raster.diffuseState.sourceId,map.id);const b=bridge.render(o,{...v,diffuse:{enabled:true}});assert.equal(b.status,'unavailable');});
test('equal-byte mask-only tampering cannot hide behind a preserved integrated radiance',async()=>{
 const s=create(),start=raw.indexOf('"estimatedFraction"'),tail=raw.slice(start),match=/([\[,]\s*)0(?:\.0)?(?=\s*[,\]])/.exec(tail);assert.ok(match,'zero-fraction fixture cell required');const at=start+match.index+match[1].length,changed=raw.slice(0,at)+'1'+raw.slice(at+1);assert.equal(changed.length,raw.length);assert.equal(JSON.parse(changed).integratedWm2nm,map.integratedWm2nm);const result=await s.load('32',async()=>changed);assert.equal(result.status,'unavailable');assert.match(result.error,/hash/);
});
